import sys
from collections import deque

def bfs_distances(start_nodes, n, adj):
    """Compute minimum distance from each node to any of the start_nodes."""
    dist = {}
    for i in range(1, n + 1):
        dist[i] = -1

    queue = deque(start_nodes)
    for node in start_nodes:
        dist[node] = 0

    while queue:
        node = queue.popleft()
        for neighbor in adj[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)

    return dist

