        adj[a].append((b, c))
        adj[b].append((a, c))

    visited = [False] * (n + 1)
    possible = True

    # Process each connected component
    for start in range(1, n + 1):
        if not visited[start]:
            # BFS to compute relative values
            values = {}  # node -> (a, b) where value = a*root + b
            queue = deque([start])
            visited[start] = True
            values[start] = (1, 0)  # root node: root = 1*root + 0

            while queue and possible:
                u = queue.popleft()
                for v, edge_type in adj[u]:
                    if v not in values:
                        # First time visiting v
                        a_u, b_u = values[u]
                        # value[v] = edge_type - value[u]
                        #             = edge_type - (a_u*root + b_u)
                        #             = (-a_u)*root + (edge_type - b_u)
                        values[v] = (-a_u, edge_type - b_u)
                        queue.append(v)
                    else:
                        # Already visited - check consistency
                        a_v, b_v = values[v]
                        a_u, b_u = values[u]
                        # Check: value[u] + value[v] == edge_type
                        # (a_u + a_v)*root == edge_type - b_u - b_v
                        if a_u + a_v == 0:
                            # No root variable - must be exactly edge_type - b_u - b_v
                            if abs(edge_type - b_u - b_v) > 1e-9:
                                possible = False
                        # else: consistent for some root value
                        pass

            if not possible:
                return "NO"

    if not possible:
        return "NO"

    # Collect all (a, b) pairs and find optimal root
    all_nodes = []
    for i in range(1, n + 1):
        if i in values:
            all_nodes.append(values[i])

    # For each node: value = a_i * root + b_i
    # Minimize sum(|a_i * root + b_i|)
    # This is convex, we can use ternary search
    def objective(root):
        return sum(abs(a * root + b) for a, b in all_nodes)

    # Ternary search for minimum
    low, high = -1e18, 1e18
    for _ in range(100):
        mid1 = low + (high - low) / 3
        mid2 = high - (high - low) / 3
        if objective(mid1) < objective(mid2):
