from typing import Tuple

def min_dist_to_origin(p0: Tuple[float, float], p1: Tuple[float, float]) -> float:
    """Find minimum distance from origin to the line segment p0-p1."""
    dx = p1[0] - p0[0]
    dy = p1[1] - p0[1]

    dot = p0[0] * dx + p0[1] * dy
    length_sq = dx * dx + dy * dy

    if abs(length_sq) < 1e-12:
        return math.sqrt(p0[0]**2 + p0[1]**2)

    if dot <= 0:
        return math.sqrt(p0[0]**2 + p0[1]**2)

    if dot >= length_sq:
        return math.sqrt(p1[0]**2 + p1[1]**2)

    return abs(p0[0] * dy - p0[1] * dx) / math.sqrt(length_sq)

def find_tangent_points(S: Tuple[float, float], T: Tuple[float, float], r: float) -> Tuple[Tuple[float, float], Tuple[float, float]]:
    """Find the two tangent points on the circle radius r visible from S in direction of T."""
    dx = T[0] - S[0]
    dy = T[1] - S[1]
    l = math.sqrt(dx*dx + dy*dy)

    theta = math.atan2(dy, dx)
    alpha = math.acos(math.max(r / l, 0.0))

    def vec_th(a):
        return (math.cos(a) * r, math.sin(a) * r)

    return vec_th(theta - alpha), vec_th(theta + alpha)


