        start = max(1, j - r + 1)
        end = min(j, m - r + 1)
        count = max(0, end - start + 1)
        col_factors.append(count)

    # Count frequencies of each row factor
    row_freq = {}
    for x in row_factors:
        row_freq[x] = row_freq.get(x, 0) + 1

    # Count frequencies of each col factor
    col_freq = {}
    for x in col_factors:
        col_freq[x] = col_freq.get(x, 0) + 1

    # Generate all possible cell weights (products of row and col factors) and their frequencies
    products = []
    for r_val, r_count in row_freq.items():
        for c_val, c_count in col_freq.items():
            prod = r_val * c_val
            products.append((prod, r_count * c_count))

    # Sort by product (cell weight) descending
    products.sort(key=lambda x: x[0], reverse=True)

    # Sum the top k weights (weighted by frequency)
    total = 0
    for i in range(k):
        total += products[i][0] * products[i][1]

    return str(total / den)

